
var gameController;
var gameWS=new WebSocket(serverString);

 /*------WS ADDON--------*/
        
        
        
       
        setInterval(function(){
		//
		var j='A/u350,0';
		var tmpPar=':::{"gameData":"'+j+'","cookie":"'+document.cookie+'","sessionId":"'+sessionStorage.getItem('sessionId')+'","gameName":"Hot27AM"}';j=tmpPar;
		gameWS.send(j);	
		},5000);
		
		
		gameWS.onmessage=function(k){
	
		    var tmpMess=k.data.split("#");

			if(tmpMess[0]=='UPDATE' && gameController.win<=0 && gameController.heq.upq!=undefined){
			
			if(gameController.xyt!=parseInt(tmpMess[1])){
				
			gameController.xyt=parseInt(tmpMess[1]);	
			gameController.nsc=parseInt(tmpMess[1]);	
			gameController.heq.upq.cdc("creditd", "#miw", [gameController.ocq(tmpMess[1]), true]);	
			
			}
			
			
			
			
			
			}	
			
		}
		
